"""Write src/cli/wide_cells.ts: the code points a terminal draws two cells wide.

They are Unicode's East Asian Width W (wide) and F (fullwidth) characters, from this Python's
`unicodedata`, and the blocks UAX #11 gives W even where they are unassigned. Run it from the
repository root with a Python whose `unicodedata.unidata_version` is the Unicode version wanted
(15.1.0 is CPython 3.13's), then commit both files:

    python3.13 -I tests/fixtures/wide_cells.py
"""

import pathlib
import sys
import unicodedata

# UAX #11's @missing W ranges: CJK ideograph blocks wide even where unassigned.
DEFAULT_WIDE = [
    (0x3400, 0x4DBF),
    (0x4E00, 0x9FFF),
    (0xF900, 0xFAFF),
    (0x20000, 0x2FFFD),
    (0x30000, 0x3FFFD),
]


def wide(code: int) -> bool:
    if unicodedata.east_asian_width(chr(code)) in ("W", "F"):
        return True
    return any(first <= code <= last for first, last in DEFAULT_WIDE)


def ranges() -> list[tuple[int, int]]:
    found: list[tuple[int, int]] = []
    for code in range(sys.maxunicode + 1):
        if not wide(code):
            continue
        if found and found[-1][1] == code - 1:
            found[-1] = (found[-1][0], code)
        else:
            found.append((code, code))
    return found


def main() -> None:
    pairs = [f"0x{first:x}, 0x{last:x}," for first, last in ranges()]
    rows = ["  " + " ".join(pairs[i : i + 4]) for i in range(0, len(pairs), 4)]
    version = unicodedata.unidata_version
    text = f"""/**
 * The code points a terminal draws two cells wide: Unicode {version}'s East Asian Width W (wide)
 * and F (fullwidth) characters, and the blocks UAX #11 gives W even where they are unassigned.
 *
 * Generated by `tests/fixtures/wide_cells.py`: run it again rather than edit this file.
 *
 * Knows about: nothing else.
 */

/** Each range's first and last code point, in order: `[first, last, first, last, ...]`. */
export const WIDE_RANGES: readonly number[] = [
{chr(10).join(rows)}
];
"""
    root = pathlib.Path(__file__).resolve().parents[2]
    root.joinpath("src", "cli", "wide_cells.ts").write_text(text)


if __name__ == "__main__":
    main()
